{"args":{"content":"import time
import threading
from collections import OrderedDict
from typing import Any, Optional
from .entry import CacheEntry

class LRUCache:
    def __init__(self, capacity: int, default_ttl: Optional[float] = None):
        if capacity <= 0:
            raise ValueError('Capacity must be positive')
        self.capacity = capacity
        self.default_ttl = default_ttl
        self._store: OrderedDict[str, CacheEntry] = OrderedDict()
        self._lock = threading.RLock()

    def _purge_expired(self, now: float) -> None:
        expired = [k for k, e in self._store.items() if e.is_expired(now)]
        for k in expired:
            del self._store[k]

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key not in self._store:
                return None
            entry = self._store[key]
            now = time.monotonic()
            if entry.is_expired(now):
                del self._store[key]
                return None
            self._store.move_to_end(key)
            return entry.value

    def put(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            now = time.monotonic()
            self._purge_expired(now)
            effective_ttl = ttl if ttl is not None else self.default_ttl
            if key in self._store:
                self._store.move_to_end(key)
            self._store[key] = CacheEntry(key, value, effective_ttl, now)
            if len(self._store) > self.capacity:
                self._store.popitem(last=False)","path":"lru/cache.py"},"call_id":"call_4","name":"patch","thought":"Now let me also check the `cache.py` for stale purging on `put()`. The task says stale items must be purged upon `get()` and `put()`. Currently `put()` doesn't purge stale items. Let me fix that too."}
